#!/usr/bin/env python3
# luxarch:targeted-guard-run hook v4 - DO NOT edit this file - it is emitted by `luxarch --emit hooks`; re-emit to update.
"""Deny a full luxarch scan piped into a filter: check one rule or one file with `--rule`.

`luxarch --rule <id>` runs only the matching rules, and `--path <file>` narrows the output to one
file. A full scan (`make arch`, or the image with no `--rule`) takes minutes on a large repo, and
filtering its output with grep, head or tail to read one rule or one file spends all of that to
throw most of it away. The whole repo's per-rule counts are in `.luxarch-status.json`
(`make status`).

PreToolUse(Bash): deny a pipeline whose first stage runs a full luxarch scan and whose later stage
is a text filter. A full scan run on its own or saved to a file, `make status`, a `--rule`,
`--sweep` or `--plan` run, the image's non-scan modes (`--doc`, `--emit`, `--changelog`, ...) and a
make dry run all pass. In a `docker run` of a luxarch image, the container's command decides, not
the image's name (`_guard_cmd.guard_runs`): `python -m pytest` in an image tagged `luxarch:…` is not
a scan, and `python -c "…main()"` with `sys.argv = ['luxarch', '--rule', 'x']` is a targeted one. A
pipeline the container's own shell runs (`… sh -c 'luxarch | grep x'`) is judged as if typed here.
`--rule` is read as the CLI reads it (`_guard_cmd.selects_rules`): a value with no token left after
splitting on commas, or one that is a variable, runs every rule. A tool call whose event cannot be
read is denied.
"""

from __future__ import annotations

import re
import shlex
import sys
from pathlib import Path

sys.path.insert(0, str(Path(__file__).parent))
from _cmdtext import (  # sibling helper, loaded by path
    SimpleCommand,
    argv_bodies,
    command_text,
    guarded,
    load_event,
    text_field,
    tool_input,
)
from _guard_cmd import guard_runs, selects_rules  # sibling helper, loaded by path

# The luxarch image, by registry ref, local tag or digest, or the variable that names it.
_IMAGE = re.compile(
    r"^(?:[\w.:-]+/)*luxarch(?::[\w.-]+)?(?:@sha256:\w+)?$"
    r"|^\$\{?LUXARCH(?:_IMAGE)?\}?$|^\$\(LUXARCH(?:_IMAGE)?\)$"
)
# `docker run` options that take no value; every other option takes the next word unless it is
# written `--opt=value`.
_FLAG_ONLY = {
    "--rm",
    "-i",
    "-t",
    "-it",
    "-ti",
    "-d",
    "--detach",
    "--init",
    "--privileged",
    "--read-only",
    "--interactive",
    "--tty",
    "-q",
    "--quiet",
    "--sig-proxy",
    "-P",
    "--publish-all",
    "--no-healthcheck",
    "--oom-kill-disable",
}
# Image arguments that make a run targeted, or not a scan at all.
_NOT_A_FULL_SCAN = {
    "--sweep",
    "--plan",
    "--emit",
    "--doc",
    "--docs",
    "--playbook",
    "--list-rules",
    "--fleet-versions",
    "--fleet-deps",
    "--changelog",
    "--new-rules",
    "--upgrade",
    "--version",
    "--help",
    "-h",
    "--map",
}
# make options that take the next word as their value, and those that run nothing.
_MAKE_VALUED = {
    "-C",
    "-f",
    "-I",
    "-o",
    "-W",
    "--directory",
    "--file",
    "--makefile",
    "--include-dir",
    "--old-file",
    "--what-if",
    "--assume-old",
    "--assume-new",
}
_MAKE_DRY = {
    "-n",
    "--dry-run",
    "--just-print",
    "--recon",
    "-q",
    "--question",
    "-p",
    "--print-data-base",
}
_LEADERS = {"time", "sudo", "nice", "command", "exec", "env"}
_FILTERS = {
    "grep",
    "egrep",
    "fgrep",
    "rg",
    "ag",
    "awk",
    "sed",
    "perl",
    "head",
    "tail",
    "jq",
    "cut",
    "wc",
    "sort",
    "uniq",
}
_STATEMENT = re.compile(r"&&|\|\||;|\n")
_PIPE = re.compile(r"\|&?")
# A redirection word (`2>&1`, `>out`, `> out`): the shell's, not the container command's.
_REDIRECTION = re.compile(r"^(?:\d+|&)?(?:>>?|<|>&|<&|>\|)(.*)$", re.S)
# A newline that continues the command: after a backslash, or after a pipe, `&&` or `||`.
_CONTINUED = re.compile(r"\\\n|(?<=\|)[ \t]*\n|(?<=&&)[ \t]*\n")


def _words(raw: str) -> list[str]:
    try:
        return shlex.split(raw)
    except ValueError:
        return raw.split()


def _command(words: list[str]) -> list[str]:
    """``words`` from the command word on: env assignments, wrappers and `timeout N` dropped."""
    i = 0
    while i < len(words):
        w = words[i].lstrip("({")
        if not w or w in _LEADERS or re.match(r"^\w+=", w):
            i += 1
        elif w == "timeout":
            i += 2
        elif w == "xargs":
            i += 1
            while i < len(words) and words[i].startswith("-"):
                i += 1
        else:
            return [w, *words[i + 1 :]]
    return []


def _make_runs_arch(args: list[str]) -> bool:
    i = 0
    while i < len(args):
        a = args[i]
        if a in _MAKE_DRY or re.match(r"^-[a-zA-Z]*[nqp][a-zA-Z]*$", a):
            return False
        if a in _MAKE_VALUED:
            i += 2
            continue
        if a.startswith("-") or "=" in a:
            i += 1
            continue
        return a.rstrip(");}") == "arch"
    return False


def _without_redirections(words: list[str]) -> list[str]:
    out: list[str] = []
    skip = False
    for w in words:
        if skip:
            skip = False  # the target of a `>` written apart from it
            continue
        m = _REDIRECTION.match(w)
        if m:
            skip = not m.group(1)
            continue
        out.append(w)
    return out


def _luxarch_container(args: list[str]) -> list[str] | None:
    """What a `docker run` of a luxarch image runs (an `--entrypoint` override first), or None for
    another image or another docker command."""
    if args[:1] == ["container"]:
        args = args[1:]
    if args[:1] != ["run"]:
        return None
    entrypoint: list[str] = []
    i = 1
    while i < len(args):
        a = args[i]
        if a == "--entrypoint" or a.startswith("--entrypoint="):
            value = (
                a.split("=", 1)[1]
                if "=" in a
                else (args[i + 1] if i + 1 < len(args) else "")
            )
            entrypoint = [value] if value else []
        if not a.startswith("-"):
            if not _IMAGE.match(a):
                return None
            return [*entrypoint, *_without_redirections(args[i + 1 :])]
        i += 1 if (a in _FLAG_ONLY or "=" in a) else 2
    return None


def _scans_all(run: list[str]) -> bool:
    """luxarch run with these arguments runs every rule."""
    flags = {r.split("=", 1)[0] for r in run if r.startswith("-")}
    return not selects_rules(run) and not flags & _NOT_A_FULL_SCAN


def _full_scan(raw: str, inside: bool = False) -> bool:
    words = _command(_words(raw))
    if not words:
        return False
    head = Path(words[0]).name
    if head == "make":
        return _make_runs_arch(words[1:])
    if head == "luxarch":  # the guard's own command, inside a container's shell
        return _scans_all(words[1:])
    if inside and head not in {"docker", "podman"}:
        # inside a luxarch container every program is read as guard-cmd reads the container's
        # command: `python -m luxarch`, `nice luxarch`, a program named by a variable
        return any(_scans_all(run) for run in guard_runs("luxarch", words))
    if head in {"docker", "podman"}:
        command = _luxarch_container(words[1:])
        return command is not None and any(
            _scans_all(run) for run in guard_runs("luxarch", command)
        )
    return False


def _container_shells(raw: str) -> list[str]:
    """The shell text a luxarch container runs (`… sh -c 'luxarch | grep x'`)."""
    words = _command(_words(raw))
    if not words or Path(words[0]).name not in {"docker", "podman"}:
        return []
    command = _luxarch_container(words[1:])
    return argv_bodies(SimpleCommand((), tuple(command), "")) if command else []


def _is_filter(raw: str) -> bool:
    words = _command(_words(raw))
    return bool(words) and Path(words[0]).name in _FILTERS


def filtered_full_scan(cmd: str, inside: bool = False) -> bool:
    """A statement of `cmd` pipes a full luxarch scan into a text filter."""
    joined = _CONTINUED.sub(lambda m: " " * len(m.group(0)), cmd)
    masked = command_text(joined)
    start = 0
    for m in [*_STATEMENT.finditer(masked), None]:
        end = m.start() if m else len(masked)
        stmt_m, stmt_r = masked[start:end], joined[start:end]
        start = m.end() if m else end
        pipes = list(_PIPE.finditer(stmt_m))
        starts = [0, *(p.end() for p in pipes)]
        ends = [*(p.start() for p in pipes), len(stmt_m)]
        stages = [(stmt_m[a:b], stmt_r[a:b]) for a, b in zip(starts, ends, strict=True)]
        # the pipeline a container's own shell runs is judged as if typed here
        if any(
            filtered_full_scan(t, inside=True)
            for s, r in stages
            if s.strip()
            for t in _container_shells(r)
        ):
            return True
        if (
            not pipes
            or not stages[0][0].strip()
            or not _full_scan(stages[0][1], inside)
        ):
            continue
        # A stage blanked by the mask (a comment, quoted data) is not a command.
        if any(_is_filter(r) for s, r in stages[1:] if s.strip()):
            return True
    return False


def main() -> int:
    ev = load_event()
    if ev.get("tool_name") != "Bash":
        return 0
    cmd = text_field(tool_input(ev), "command")
    if filtered_full_scan(cmd):
        print(
            "DENIED: a full luxarch scan filtered through grep, head or tail runs every rule "
            "to read one.\n"
            "Run only what you need: `luxarch --rule <id>` (exact or substring, repeatable or "
            "comma-separated) runs only the matching rules, and `--path <file>` narrows the output "
            "to one file. The whole repo's per-rule counts are in `.luxarch-status.json` "
            "(`make status`). A full scan you want to read whole runs without a filter.",
            file=sys.stderr,
        )
        return 2
    return 0


sys.exit(guarded(main, "targeted-guard-run"))
